import React, {useCallback, useRef} from 'react';
import type {RefObject} from 'react';

import {Check} from '@gravity-ui/icons';
import {Icon} from '@gravity-ui/uikit';

import type {SuggestProps} from '~/src/components/Suggest';

import {cnSelectSearch} from '../SelectSearch.classname';
import type {Option} from '../types';

export type UseSelectSearchProps<V> = {
    customRenderItem?: SuggestProps['renderItem'];
    values: Option<V>[];
};

export const useSelectSearch = <V,>({values, customRenderItem}: UseSelectSearchProps<V>) => {
    const textInputRef = useRef<RefObject<HTMLInputElement>>();

    const defaultRenderItem = useCallback(
        (option: Option<V>) => {
            const {value, content, disabled} = option;
            const active = values.some((item) => item.value === value);

            return (
                <div className={cnSelectSearch('option', {disabled})}>
                    <Icon
                        className={cnSelectSearch('selected-icon', {active})}
                        data={Check}
                        size={16}
                    />
                    <span>{content}</span>
                </div>
            );
        },
        [values],
    );

    return {
        textInputRef,
        renderItem: customRenderItem || defaultRenderItem,
    };
};
